function validate(input) {
  const [{ Customer = [], Orders = [], Seller = [] }] = input;
  const customers = new Set(), sellers = new Set(), orders = new Set();
  for (const [id, name] of Customer) {
    if (id === null || name === null) return 'Customer rows may not contain null.';
    if (customers.has(id)) return `customer_id ${id} appears twice in Customer.`;
    customers.add(id);
  }
  for (const [id, name] of Seller) {
    if (id === null || name === null) return 'Seller rows may not contain null.';
    if (sellers.has(id)) return `seller_id ${id} appears twice in Seller.`;
    sellers.add(id);
  }
  for (const row of Orders) {
    if (row.some((v) => v === null)) return 'Orders rows may not contain null.';
    const [id, date, cost, customer, seller] = row;
    if (orders.has(id)) return `order_id ${id} appears twice in Orders.`;
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) return 'Dates must look like 2020-01-31.';
    if (cost <= 0) return 'order_cost must be positive.';
    if (!customers.has(customer)) return `Order ${id} names unknown customer ${customer}.`;
    if (!sellers.has(seller)) return `Order ${id} names unknown seller ${seller}.`;
    orders.add(id);
  }
  return null;
}

