function generate(rand, size) {
  const pick = (list) => list[Math.floor(rand() * list.length)];
  const names = ['Daniel', 'Elizabeth', 'Frank', 'Grace', 'Henry', 'Ivy', 'Jack'];
  const dates = ['2019-02-11', '2019-12-31', '2020-01-01', '2020-03-01', '2020-06-15', '2020-12-31', '2021-01-01', '2021-07-04'];
  const small = size === 'small';
  const sellerCount = small ? Math.floor(rand() * 7) : 800;
  const customerCount = small ? 1 + Math.floor(rand() * 4) : 500;
  const orderCount = small && sellerCount > 0 ? Math.floor(rand() * 9) : small ? 0 : 2000;
  const Seller = [], Customer = [], Orders = [];
  for (let id = 1; id <= sellerCount; id++) Seller.push([id, small ? pick(names) : `${pick(names)}${id}`]);
  for (let id = 1; id <= customerCount; id++) Customer.push([100 + id, pick(['Alice', 'Bob', 'Charlie', 'Dana'])]);
  for (let id = 1; id <= orderCount; id++) {
    const date = small ? pick(dates) : `${2019 + Math.floor(rand() * 3)}-${String(1 + Math.floor(rand() * 12)).padStart(2, '0')}-${String(1 + Math.floor(rand() * 28)).padStart(2, '0')}`;
    // Large tables give most orders to a few sellers so many sellers have none in 2020.
    const seller = small ? 1 + Math.floor(rand() * sellerCount) : 1 + Math.floor(rand() * rand() * sellerCount);
    Orders.push([id, date, 100 + Math.floor(rand() * 2000), 101 + Math.floor(rand() * customerCount), seller]);
  }
  return [{ Customer, Orders, Seller }];
}
